1	import * as THREE from "three";
2	import { AnimationLoop } from "./AnimationLoop.js";
3	import { Scene } from "./Scene.js";
4	import { ModelLoader } from "./ModelLoader.js";
5	import { PostProcessor } from "./PostProcessor.js";
6	import { BackgroundManager } from "../manager/BackgroundManager.js";
7	import { Helpers } from "../utils/Helpers.js";
8	import type { SceneObject } from "../core/SceneObject.js";
9	import { hasWebGLRendererFeatures } from "../types/engine.types.js";
10	import type {
11	  RendererLike,
12	  RendererBackend,
13	  HasPositionSet,
14	} from "../types/engine.types.js";
15	import { hasPositionSet } from "../types/engine.types.js";
16	import type {
17	  EngineOptions,
18	  RenderBudgetOptions,
19	} from "../types/engine.types.js";
20	import type { ResponsiveSnapshot } from "../types/runtime.types.js";
21	import type {
22	  SceneFromState,
23	  CameraVars,
24	  ObjectVars,
25	} from "../types/core.types.js";
26	import { getDefaultThreeConfig } from "../config/base.config.js";
27	import { ResponsiveRuntime } from "../runtime/ResponsiveRuntime.js";
28	import {
29	  camera as cameraId,
30	  cameraTarget as cameraTargetId,
31	  THREE_LAYER_EARTH,
32	  THREE_LAYER_MARQUEE,
33	  THREE_LAYER_ROCKET,
34	} from "./setup.js";
35	
36	const DEFAULT_RENDER_BUDGET: Required<RenderBudgetOptions> = {
37	  budgetMs: 33,
38	  mode: "performance",
39	  enterSkipFrames: 2,
40	  exitSkipFrames: 8,
41	};
42	export class Engine {
43	  private _scene: Scene;
44	  private _camera: THREE.PerspectiveCamera;
45	  private _cameraTarget: THREE.Object3D;
46	  private _cameraTargetFollow: THREE.Object3D | null = null;
47	  private _cameraTargetFollowAnchorNode: THREE.Object3D | null = null;
48	  private _cameraTargetFollowLocalAnchor: THREE.Vector3 | null = null;
49	  private _followBounds = new THREE.Box3();
50	  private _followCenter = new THREE.Vector3();
51	  private _followWorldPos = new THREE.Vector3();
52	  private _renderer: RendererLike | null = null;
53	  private _postProcessor: PostProcessor | null = null;
54	  private _backgroundManager: BackgroundManager | null = null;
55	  private _rendererBackend: RendererBackend = "webgl";
56	  private _loader: ModelLoader;
57	  private _animationLoop: AnimationLoop | null = null;
58	  private _lastDelta = 0;
59	  private _contextLost = false;
60	  private _onContextLost: ((event: Event) => void) | null = null;
61	  private _onContextRestored: ((event: Event) => void) | null = null;
62	  private _opts: EngineOptions;
63	  private _pixelRatioMax: number;
64	  private _renderBudget: Required<RenderBudgetOptions>;
65	  private _renderModeState = {
66	    skipActive: false,
67	    exceededFrames: 0,
68	    stableFrames: 0,
69	  };
70	  private _didWarnPostProcessingFallback = false;
71	  private readonly _defaultThreeConfig = getDefaultThreeConfig();
72	
73	  constructor(opts: EngineOptions = {}) {
74	    this._opts = opts;
75	    this._renderBudget = this._resolveRenderBudget(opts.renderBudget);
76	    const pr = opts.pixelRatioMax;
77	    this._pixelRatioMax =
78	      typeof pr === "number" && Number.isFinite(pr) && pr > 0
79	        ? pr
80	        : this._defaultThreeConfig.pixelRatioMax;
81	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
82	    const aspect = responsive.viewportWidth / responsive.viewportHeight;
83	    const cam = opts.camera ?? {};
84	    const fov = cam.fov ?? this._defaultThreeConfig.camera.fov;
85	    const near = cam.near ?? this._defaultThreeConfig.camera.near;
86	    const far = cam.far ?? this._defaultThreeConfig.camera.far;
87	    this._camera = new THREE.PerspectiveCamera(fov, aspect, near, far);
88	    this._camera.scale.set(1, 1, 1);
89	    this._camera.layers.enable(THREE_LAYER_EARTH);
90	    this._camera.layers.enable(THREE_LAYER_MARQUEE);
91	    this._camera.layers.enable(THREE_LAYER_ROCKET);
92	    if (cam.position) {
93	      this._camera.position.set(
94	        cam.position.x ?? 0,
95	        cam.position.y ?? 0,
96	        cam.position.z ?? 0,
97	      );
98	    }
99	    const sceneFactory = opts.dependencies?.sceneFactory;
100	    this._scene = sceneFactory ? (sceneFactory() as Scene) : new Scene();
101	    this._cameraTarget = new THREE.Object3D();
102	    this._cameraTarget.name = cameraTargetId;
103	    const ct = opts.cameraTarget?.position;
104	    this._cameraTarget.position.set(ct?.x ?? 0, ct?.y ?? 0, ct?.z ?? 0);
105	    const loaderFactory = opts.dependencies?.modelLoaderFactory;
106	    this._loader = loaderFactory
107	      ? (loaderFactory() as ModelLoader)
108	      : new ModelLoader();
109	  }
110	
111	  init(): boolean {
112	    const targetCanvas = this._resolveTargetCanvas();
113	    if (!targetCanvas) return false;
114	
115	    const scene = this._scene.three;
116	    scene.add(this._cameraTarget);
117	
118	    this._scene.registerObject(cameraId, this._camera);
119	    this._scene.registerObject(cameraTargetId, this._cameraTarget);
120	    const cfg = this._opts.scene ?? {};
121	    scene.background =
122	      cfg.background != null ? new THREE.Color(cfg.background) : null;
123	    const fogOpt = cfg.fog;
124	    scene.fog =
125	      fogOpt != null && typeof fogOpt === "object" && "far" in fogOpt
126	        ? new THREE.Fog(
127	            fogOpt.color ?? 0x000000,
128	            fogOpt.near ?? 1000,
129	            fogOpt.far ?? 15000,
130	          )
131	        : null;
132	
133	    const rendererOpts = this._opts.renderer ?? {};
134	    this._renderer = this._createRenderer(targetCanvas, rendererOpts);
135	    if (!this._renderer) return false;
136	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
137	    const w = responsive.viewportWidth;
138	    const h = responsive.viewportHeight;
139	    this._renderer.setSize?.(w, h);
140	    this._renderer.setPixelRatio?.(Math.min(responsive.render.clampedPixelRatio, this._pixelRatioMax));
141	    if (
142	      this._renderer &&
143	      hasWebGLRendererFeatures(this._renderer) &&
144	      this._renderer.shadowMap
145	    ) {
146	      const shadowOpt = this._opts.shadowMap ?? {};
147	      this._renderer.shadowMap.enabled = shadowOpt.enabled ?? false;
148	      this._renderer.shadowMap.type = shadowOpt.type ?? THREE.PCFSoftShadowMap;
149	    }
150	    this._renderer.toneMapping = THREE.ACESFilmicToneMapping;
151	    this._renderer.toneMappingExposure = 0.56;
152	    this._renderer.outputColorSpace = THREE.SRGBColorSpace;
153	    this._attachContextEvents();
154	
155	    this._camera.aspect = w / h;
156	    this._camera.updateProjectionMatrix();
157	
158	    const postProcessorOptions = this._resolvePostProcessorOptions();
159	    this._postProcessor =
160	      this._rendererBackend === "webgl" &&
161	      this._renderer instanceof THREE.WebGLRenderer &&
162	      postProcessorOptions
163	        ? new PostProcessor(
164	            this._renderer,
165	            scene,
166	            this._camera,
167	            postProcessorOptions,
168	          )
169	        : null;
170	
171	    const loadModel = (path: string) => this._loadModel(path);
172	    const loadModelWithAnimation = (path: string) =>
173	      this._loader.loadGLTF(this._scene.three, path, {
174	        addToScene: false,
175	      });
176	    const loadTexture = (path: string) => this._loader.loadTexture(path);
177	    const loadHdrTexture = (path: string) => this._loader.loadHdrTexture(path);
178	    const compileScene = (camera?: THREE.Camera) =>
179	      this._compileScene(camera ?? this._camera);
180	    const prepareTexture = (texture: THREE.Texture) =>
181	      this._prepareTexture(texture);
182	    const getObject = (id: string) => this._scene.getObject(id);
183	    const registerObject = (
184	      id: string,
185	      object: THREE.Object3D | Record<string, unknown>,
186	    ) => this._scene.registerObject(id, object);
187	    const unregisterObject = (id: string) => this._scene.unregisterObject(id);
188	    this._scene.setContext({
189	      scene: this._scene.three,
190	      camera: this._camera,
191	      renderer: this._renderer,
192	      rendererBackend: this._rendererBackend,
193	      compileScene,
194	      prepareTexture,
195	      getObject,
196	      registerObject,
197	      unregisterObject,
198	      loadModel,
199	      loadModelWithAnimation,
200	      loadTexture,
201	      loadHdrTexture,
202	    });
203	    if (this._renderer instanceof THREE.WebGLRenderer) {
204	      this._backgroundManager = new BackgroundManager(
205	        this._renderer,
206	        this._scene.three,
207	        this._camera,
208	      );
209	      this._scene.registerObject(
210	        "env.backgroundManager.runtime",
211	        this._backgroundManager as unknown as Record<string, unknown>,
212	      );
213	    }
214	    return true;
215	  }
216	
217	  private _resolveTargetCanvas(): HTMLCanvasElement | null {
218	    const providedCanvas = this._opts.canvasElement;
219	    if (providedCanvas instanceof HTMLCanvasElement) {
220	      return providedCanvas;
221	    }
222	    const canvasId = this._opts.canvasId ?? "canvas";
223	    const el = document.getElementById(canvasId);
224	    if (!el) return null;
225	    if (el instanceof HTMLCanvasElement) {
226	      return el;
227	    }
228	    const nestedCanvas = el.querySelector("canvas");
229	    if (nestedCanvas instanceof HTMLCanvasElement) {
230	      return nestedCanvas;
231	    }
232	    return this._createCanvas(el);
233	  }
234	
235	  private _createRenderer(
236	    canvas: HTMLCanvasElement,
237	    rendererOpts: EngineOptions["renderer"] = {},
238	  ): RendererLike | null {
239	    const performance = ResponsiveRuntime.getDefault().getSnapshot().performance;
240	    const webglContext =
241	      canvas.getContext("webgl2") ??
242	      canvas.getContext("webgl") ??
243	      canvas.getContext("experimental-webgl");
244	    if (!webglContext) return null;
245	    this._rendererBackend = "webgl";
246	    try {
247	      return new THREE.WebGLRenderer({
248	        canvas,
249	        antialias: rendererOpts.antialias ?? performance.rendererAntialias,
250	        alpha: rendererOpts.alpha ?? false,
251	        powerPreference:
252	          rendererOpts.powerPreference ?? performance.rendererPowerPreference,
253	      });
254	    } catch (error) {
255	      return null;
256	    }
257	  }
258	
259	  private _createCanvas(container: HTMLElement): HTMLCanvasElement {
260	    const canvas = document.createElement("canvas");
261	    canvas.id = "canvas-webgl";
262	    container.appendChild(canvas);
263	    return canvas;
264	  }
265	
266	  private async _loadModel(path: string): Promise<THREE.Object3D> {
267	    const result = await this._loader.loadGLTF(this._scene.three, path, {
268	      addToScene: false,
269	    });
270	    if (!result.model) throw new Error(`Failed to load model: ${path}`);
271	    return result.model;
272	  }
273	
274	  runModelLoad(path: string): Promise<THREE.Object3D> {
275	    return this._loadModel(path);
276	  }
277	
278	  async setObject(id: string, object: SceneObject): Promise<void> {
279	    await this._scene.addObject(id, object);
280	  }
281	
282	  getScene(): Scene {
283	    return this._scene;
284	  }
285	
286	  setState(state: SceneFromState): void {
287	    const cam = state.camera;
288	    if (cam) {
289	      this._applyCamState(cam);
290	    }
291	    const camTarget = state.cameraTarget;
292	    if (camTarget?.position) {
293	      this.setCameraTargetPosition(
294	        this._num(camTarget.position.x),
295	        this._num(camTarget.position.y),
296	        this._num(camTarget.position.z),
297	      );
298	    }
299	    const scene = this._scene;
300	    for (const [targetId, vars] of Object.entries(state)) {
301	      if (
302	        targetId === cameraId ||
303	        targetId === cameraTargetId ||
304	        vars == null ||
305	        typeof vars !== "object"
306	      )
307	        continue;
308	      const obj = scene.getObject(targetId);
309	      if (!obj) continue;
310	      if (hasPositionSet(obj)) {
311	        this._applyVector3(obj, vars as ObjectVars);
312	        this._applyScalarProps(
313	          obj as unknown as Record<string, unknown>,
314	          vars as Record<string, unknown>,
315	        );
316	        continue;
317	      }
318	      if (!this._isPlainRecord(obj)) continue;
319	      this._applyScalarProps(obj, vars as Record<string, unknown>);
320	    }
321	  }
322	
323	  private _applyCamState(cam: CameraVars): void {
324	    this._applyVector3(this._camera, cam, false);
325	    if (cam.fov == null || !Number.isFinite(cam.fov)) return;
326	    this._camera.fov = cam.fov;
327	    this._camera.updateProjectionMatrix();
328	  }
329	
330	  private _num(v: number | undefined): number {
331	    return v != null && Number.isFinite(v) ? v : 0;
332	  }
333	
334	  private _applyVector3(
335	    obj: HasPositionSet,
336	    vars: ObjectVars | CameraVars,
337	    applyRotation = true,
338	  ): void {
339	    if (vars.position)
340	      obj.position.set(
341	        this._num(vars.position.x),
342	        this._num(vars.position.y),
343	        this._num(vars.position.z),
344	      );
345	    if (applyRotation && "rotation" in vars && vars.rotation && obj.rotation) {
346	      const r = Helpers.rotationDegToRad({
347	        x: this._num(vars.rotation.x),
348	        y: this._num(vars.rotation.y),
349	        z: this._num(vars.rotation.z),
350	      });
351	      obj.rotation.set(r.x, r.y, r.z);
352	    }
353	    if (vars.scale && obj.scale)
354	      obj.scale.set(
355	        this._num(vars.scale.x),
356	        this._num(vars.scale.y),
357	        this._num(vars.scale.z),
358	      );
359	  }
360	
361	  private _isPlainRecord(obj: unknown): obj is Record<string, unknown> {
362	    if (
363	      obj == null ||
364	      typeof obj !== "object" ||
365	      Array.isArray(obj) ||
366	      obj instanceof THREE.Object3D
367	    ) {
368	      return false;
369	    }
370	    const proto = Object.getPrototypeOf(obj);
371	    return proto === Object.prototype || proto === null;
372	  }
373	
374	  private _applyScalarProps(
375	    target: Record<string, unknown>,
376	    vars: Record<string, unknown>,
377	  ): void {
378	    for (const [key, value] of Object.entries(vars)) {
379	      if (key === "position" || key === "rotation" || key === "scale") continue;
380	      if (typeof value === "number" && Number.isFinite(value)) {
381	        target[key] = value;
382	        continue;
383	      }
384	      if (typeof value === "boolean" || typeof value === "string") {
385	        target[key] = value;
386	        continue;
387	      }
388	      if (this._isPlainRecord(value)) {
389	        const current = target[key];
390	        const nextTarget = this._isPlainRecord(current) ? current : {};
391	        target[key] = nextTarget;
392	        this._applyScalarProps(nextTarget, value);
393	      }
394	    }
395	  }
396	
397	  getCamera(): THREE.PerspectiveCamera {
398	    return this._camera;
399	  }
400	
401	  getCameraTarget(): THREE.Object3D {
402	    return this._cameraTarget;
403	  }
404	
405	  getObjectById(id: string): unknown {
406	    return this._scene.getObject(id);
407	  }
408	
409	  getObjectIds(): string[] {
410	    return this._scene.getObjectIds();
411	  }
412	
413	  getSceneObjectById(id: string): SceneObject | null {
414	    return this._scene.getSceneObject(id);
415	  }
416	
417	  removeSceneObject(id: string): void {
418	    this._scene.removeObject(id);
419	  }
420	
421	  setCameraTargetPosition(x: number, y: number, z: number): void {
422	    this._cameraTargetFollow = null;
423	    this._cameraTargetFollowAnchorNode = null;
424	    this._cameraTargetFollowLocalAnchor = null;
425	    this._cameraTarget.position.set(
426	      Number.isFinite(x) ? x : this._cameraTarget.position.x,
427	      Number.isFinite(y) ? y : this._cameraTarget.position.y,
428	      Number.isFinite(z) ? z : this._cameraTarget.position.z,
429	    );
430	  }
431	
432	  setFollowObject(object3D: THREE.Object3D): void {
433	    this._cameraTargetFollow = object3D;
434	    this._cameraTargetFollowAnchorNode = null;
435	    this._cameraTargetFollowLocalAnchor = null;
436	    const namedAnchor = object3D.getObjectByName("cameraAnchor");
437	    if (namedAnchor) {
438	      this._cameraTargetFollowAnchorNode = namedAnchor;
439	    } else {
440	      this._followBounds.setFromObject(object3D);
441	      if (!this._followBounds.isEmpty()) {
442	        this._followBounds.getCenter(this._followCenter);
443	        this._cameraTargetFollowLocalAnchor = object3D.worldToLocal(
444	          this._followCenter.clone(),
445	        );
446	      }
447	    }
448	    this._cameraTarget.position.copy(this._resolveFollowAnchor(object3D));
449	  }
450	
451	  offFollowObject(): void {
452	    this._cameraTargetFollow = null;
453	    this._cameraTargetFollowAnchorNode = null;
454	    this._cameraTargetFollowLocalAnchor = null;
455	  }
456	
457	  runBlendObject(
458	    object3D: THREE.Object3D,
459	    duration: number,
460	    animate?: (
461	      target: THREE.Vector3,
462	      destination: THREE.Vector3,
463	      duration: number,
464	    ) => void,
465	  ): void {
466	    this.offFollowObject();
467	    const anchor = this._resolveFollowAnchor(object3D);
468	    if (animate) {
469	      animate(this._cameraTarget.position, anchor, duration);
470	      return;
471	    }
472	    this._cameraTarget.position.copy(anchor);
473	  }
474	
475	  private _resolveFollowAnchor(object3D: THREE.Object3D): THREE.Vector3 {
476	    if (this._cameraTargetFollowAnchorNode) {
477	      this._cameraTargetFollowAnchorNode.updateWorldMatrix(true, false);
478	      this._cameraTargetFollowAnchorNode.getWorldPosition(this._followWorldPos);
479	      return this._followWorldPos;
480	    }
481	    object3D.updateWorldMatrix(true, false);
482	    if (this._cameraTargetFollowLocalAnchor) {
483	      this._followWorldPos
484	        .copy(this._cameraTargetFollowLocalAnchor)
485	        .applyMatrix4(object3D.matrixWorld);
486	      return this._followWorldPos;
487	    }
488	    this._followBounds.setFromObject(object3D);
489	    if (!this._followBounds.isEmpty()) {
490	      this._followBounds.getCenter(this._followCenter);
491	      return this._followCenter;
492	    }
493	    object3D.getWorldPosition(this._followWorldPos);
494	    return this._followWorldPos;
495	  }
496	
497	  getRenderer(): RendererLike | null {
498	    return this._renderer;
499	  }
500	
501	  getPostProcessor(): PostProcessor | null {
502	    return this._postProcessor;
503	  }
504	
505	  getBackgroundManager(): BackgroundManager | null {
506	    return this._backgroundManager;
507	  }
508	
509	  start(onUpdate: (deltaTime: number) => void, onRender: () => void): void {
510	    if (this._animationLoop) return;
511	    this._animationLoop = new AnimationLoop({
512	      budgetMs: this._renderBudget.budgetMs,
513	      onUpdate: (dt) => {
514	        this._lastDelta = dt;
515	        this._scene.update(dt);
516	        this._backgroundManager?.update(dt);
517	        onUpdate(dt);
518	      },
519	      onRender: () => {
520	        if (this._contextLost) return;
521	        if (this._cameraTargetFollow) {
522	          this._cameraTarget.position.copy(
523	            this._resolveFollowAnchor(this._cameraTargetFollow),
524	          );
525	        }
526	        this._camera.lookAt(this._cameraTarget.position);
527	        onRender();
528	        const frameExceeded = this._animationLoop?.frameExceeded ?? false;
529	        const skipPost = this._shouldSkipPostProcessing(frameExceeded);
530	        this._renderMainScene(skipPost);
531	      },
532	    });
533	    this._animationLoop.start();
534	  }
535	
536	  stop(): void {
537	    this._animationLoop?.stop();
538	    this._resetRenderModeState();
539	  }
540	
541	  setViewport(width: number, height: number): void {
542	    const dpr = Math.min(
543	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
544	      this._pixelRatioMax,
545	    );
546	    this._camera.aspect = width / height;
547	    this._camera.updateProjectionMatrix();
548	    this._renderer?.setPixelRatio?.(dpr);
549	    this._renderer?.setSize?.(width, height);
550	    this._postProcessor?.resize(width, height, dpr);
551	    this._backgroundManager?.resize(width, height, dpr);
552	  }
553	
554	  applyResponsiveSnapshot(snapshot: ResponsiveSnapshot): void {
555	    this._pixelRatioMax = snapshot.render.pixelRatioMax;
556	    this.setViewport(snapshot.viewportWidth, snapshot.viewportHeight);
557	  }
558	
559	  dispose(): void {
560	    this.stop();
561	    this._animationLoop?.dispose();
562	    this._animationLoop = null;
563	    this._postProcessor?.dispose();
564	    this._postProcessor = null;
565	    this._backgroundManager?.dispose();
566	    this._backgroundManager = null;
567	    this._loader.dispose();
568	    if (this._cameraTarget.parent)
569	      this._cameraTarget.parent.remove(this._cameraTarget);
570	    this._cameraTargetFollow = null;
571	    this._cameraTargetFollowAnchorNode = null;
572	    this._cameraTargetFollowLocalAnchor = null;
573	    this._scene.dispose();
574	    this._detachContextEvents();
575	    this._renderer?.dispose?.();
576	    this._renderer = null;
577	  }
578	
579	  private _attachContextEvents(): void {
580	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
581	    const canvas = this._renderer.domElement;
582	    this._onContextLost = (event: Event): void => {
583	      const webglEvent = event as Event & { preventDefault?: () => void };
584	      webglEvent.preventDefault?.();
585	      this._contextLost = true;
586	      this._animationLoop?.stop();
587	    };
588	    this._onContextRestored = (): void => {
589	      this._contextLost = false;
590	      this._animationLoop?.start();
591	    };
592	    canvas.addEventListener("webglcontextlost", this._onContextLost);
593	    canvas.addEventListener("webglcontextrestored", this._onContextRestored);
594	  }
595	
596	  private _detachContextEvents(): void {
597	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
598	    const canvas = this._renderer.domElement;
599	    if (this._onContextLost) {
600	      canvas.removeEventListener("webglcontextlost", this._onContextLost);
601	    }
602	    if (this._onContextRestored) {
603	      canvas.removeEventListener(
604	        "webglcontextrestored",
605	        this._onContextRestored,
606	      );
607	    }
608	    this._onContextLost = null;
609	    this._onContextRestored = null;
610	    this._contextLost = false;
611	  }
612	
613	  private _resolveRenderBudget(
614	    options: RenderBudgetOptions | undefined,
615	  ): Required<RenderBudgetOptions> {
616	    const budgetMs =
617	      Number.isFinite(options?.budgetMs as number) &&
618	      (options?.budgetMs as number) > 0
619	        ? (options?.budgetMs as number)
620	        : DEFAULT_RENDER_BUDGET.budgetMs;
621	    const mode =
622	      options?.mode === "consistent" || options?.mode === "performance"
623	        ? options.mode
624	        : DEFAULT_RENDER_BUDGET.mode;
625	    const enterSkipFrames =
626	      Number.isFinite(options?.enterSkipFrames as number) &&
627	      (options?.enterSkipFrames as number) > 0
628	        ? Math.floor(options?.enterSkipFrames as number)
629	        : DEFAULT_RENDER_BUDGET.enterSkipFrames;
630	    const exitSkipFrames =
631	      Number.isFinite(options?.exitSkipFrames as number) &&
632	      (options?.exitSkipFrames as number) > 0
633	        ? Math.floor(options?.exitSkipFrames as number)
634	        : DEFAULT_RENDER_BUDGET.exitSkipFrames;
