132	export class ObjectSetup implements ISetup<
133	  [Engine, PageConfig],
134	  Promise<void>
135	> {
136	  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
137	  private readonly _configRuntime = new ObjectConfigRuntime();
138	  private _disposed = false;
139	  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
140	    Partial<Record<keyof ObjectOptionsByKey, string>>
141	  > = {
142	    [sceneLights]: "env.light",
143	  };
144	
145	  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
146	    for (const [id, spec] of Object.entries(registry)) {
147	      this._registry.set(id, spec);
148	    }
149	  }
150	
151	  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
152	    this._registry.set(id, spec);
153	  }
154	
155	  register(id: string, spec: ObjectRegistrationSpec): void {
156	    this.registerFactory(id, spec);
157	  }
158	
159	  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
160	    if (this._disposed) return;
161	    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
162	      const object = this._createConfiguredObject(
163	        spec,
164	        pageConfig.objectOptions,
165	        pageConfig.initialState,
166	      );
167	      await engine.setObject(id, object);
168	      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
169	    }
170	  }
171	
172	  dispose(): void {
173	    if (this._disposed) return;
174	    this._disposed = true;
175	    this._registry.clear();
176	  }
177	
178	  private _getEnabledSpecs(
179	    pageConfig: PageConfig,
180	  ): Array<[string, ObjectRegistrationSpec]> {
181	    const enabledSpecs: Array<[string, ObjectRegistrationSpec]> = [];
182	    for (const [id, enabled] of Object.entries(pageConfig.objects)) {
183	      if (!enabled) continue;
184	      const spec = this._registry.get(id);
185	      if (!spec) continue;
186	      enabledSpecs.push([id, spec]);
187	    }
188	    return enabledSpecs;
189	  }
190	
191	  private _createConfiguredObject(
192	    spec: ObjectRegistrationSpec,
193	    pageOptions: PageConfig["objectOptions"] | undefined,
194	    initialState: PageConfig["initialState"] | undefined,
195	  ): SceneObject {
196	    const object = spec.create();
197	    const resolvedConfig = this._configRuntime.resolve(
198	      spec.id,
199	      pageOptions,
200	      initialState,
201	    );
202	    spec.applyOptions?.(object, resolvedConfig.options);
203	    if (resolvedConfig.effects && typeof object.setEffects === "function") {
204	      object.setEffects(resolvedConfig.effects);
205	    }
206	    return object;
207	  }
208	
209	  private _registerEnvironmentAlias(
210	    engine: Engine,
211	    objectId: keyof ObjectOptionsByKey,
212	  ): void {
213	    const envAlias = ObjectSetup._ENV_ALIAS_BY_OBJECT_ID[objectId];
214	    if (!envAlias) return;
215	    const target = engine.getObjectById(objectId as string);
216	    if (!target || typeof target !== "object") return;
217	    engine
218	      .getScene()
219	      .registerObject(envAlias, target as Record<string, unknown>);
220	  }
221	}
